  min-height:52px; padding:13px 20px; border:1px solid var(--camp-line); border-radius:0;
  color:var(--camp-ink); background:none; box-shadow:none; clip-path:none; transform:none;
  font:500 19px/1.45 var(--font-ui); transition:background 160ms ease,color 160ms ease,border-color 160ms ease;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act]::after { content:none; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act].base-command-primary { color:#fff5e9; background:var(--camp-action); border-color:transparent; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act]:hover:not(:disabled) { color:var(--camp-ink); background:#7b886517; border-color:var(--camp-accent); box-shadow:none; transform:none; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act].base-command-primary:hover:not(:disabled) { color:#fff5e9; background:var(--camp-action-hover); border-color:transparent; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act]:disabled { opacity:.48; background:#68706513; color:var(--camp-muted); border-color:var(--camp-line); }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .trade-v5-checkout button.base-command[data-act].is-confirming { color:#fff5e9; background:#8c5038; border-color:transparent; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) :is(button,input,select,summary):focus-visible { outline:1px solid var(--camp-accent); outline-offset:4px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) [hidden] { display:none; }
@media (prefers-reduced-motion:reduce) {
  #overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3 .stash-cell,.person-pool-card,.collection-card) { transition:none; }
  #overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3 .stash-cell,.person-pool-card,.collection-card):hover:not(:disabled) { transform:none; }
}

