#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-page:has(> :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2)) {
  --camp-bg:#242a29; --camp-paper:#242a29; --camp-sheet:#e6e1d6;
  --camp-ink:#eeeae1; --camp-muted:#a9b0a9; --camp-sub:#a9b0a9;
  --camp-line:#d3d8ce24; --camp-dark:#303937; --camp-accent:#bac2b3;
  --camp-brass:#b9c1b3; --camp-blue:#b9c1b3; --camp-action:#a76344;
  --camp-action-hover:#bc7752; --camp-room-hover:#eeeae109; --camp-room-selected:#dfe7d111;
  --room-gap:clamp(28px,calc(var(--game-layout-width, 100vw) * 0.038),64px); --room-pad:clamp(28px,calc(var(--game-layout-width, 100vw) * 0.044000000000000004),76px);
