changes.before:
/* ══ 背包 v2 玻璃界面（2026-10-15 WF-bag-redesign-1015 实装，老板拍板绝区零方向）══
   景深背景 + 玻璃拟态：左栏分区钮 / 轻量格子（真实卡面+物资图标+数量+稀有度晕染）/ 独立卡牌详情。
   拖拽浮影与落点高亮的基础样式仍在 scenes.css（.bag-ghost/.bag-slot.dragging/.bag-slot.drop-here）。 */
/* 壳使用 1920×1080 布局坐标，交给 html 的统一 zoom 缩放一次。
   vw/vh 是浏览器显示尺寸，在 zoom 内再次使用会把整页缩到左上角。 */
body #overlay.bag-full { padding: 0; display: block; }
body #overlay .card.bag-page {
  width: var(--game-layout-width, 100%); max-width: var(--game-layout-width, 100%);
  height: var(--game-layout-height, 100%); max-height: var(--game-layout-height, 100%);
  margin: 0; border: 0; border-radius: 0; padding: 0; box-shadow: none;
  transform: none !important; translate: none; scale: none;
}
body #overlay .card.bag-page #ovBody { width: 100%; height: 100%; max-height: none; overflow: hidden; }
body #overlay .card.bag-page .bag-view.bag-v2 {
  position: relative; overflow: hidden; height: 100%; width: 100%; box-sizing: border-box;
  max-width: none; margin: 0; padding: 0;
  background: #0b1017; color: #f2f4f6; font-size: 22px; text-align: left;
}
body #overlay .card.bag-page .bag-v2 .bag-bg {
  position: absolute; inset: -40px; width: calc(100% + 80px); height: calc(100% + 80px);
  object-fit: cover; filter: blur(22px) brightness(.5) saturate(1.25); z-index: 0; pointer-events: none;
}
body #overlay .card.bag-page .bag-v2 .bag-shell {
  position: relative; z-index: 1; height: 100%; min-height: 0; box-sizing: border-box;
  display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 24px; padding: 28px 34px;
}
body #overlay .card.bag-page .bag-v2 .bag-rail,
body #overlay .card.bag-page .bag-v2 .bag-board,
body #overlay .card.bag-page .bag-v2 .bag-detail {
  background: rgba(14, 18, 26, .52); backdrop-filter: blur(26px) saturate(1.35);
  -webkit-backdrop-filter: blur(26px) saturate(1.35);
  border: 1px solid rgba(255, 255, 255, .10); border-radius: 20px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, .32);
}
/* 退出键已在左栏内，随分区沿同一中线排布；不再预留悬浮按钮的顶部空洞。 */
body #overlay .card.bag-page .bag-v2 .bag-rail { display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 20px 10px; box-sizing: border-box; }
body #overlay .card.bag-page .bag-v2 .bag-rz {
  position: relative; width: 84px; height: 88px; border: 0; border-radius: 16px; cursor: pointer;
  background: transparent; color: #aebfc9; display: flex; flex-direction: column; gap: 7px; align-items: center; justify-content: center;
  transition: background .2s, color .2s, transform .2s;
}
body #overlay .card.bag-page .bag-v2 .bag-rz svg { width: 30px; height: 30px; }
body #overlay .card.bag-page .bag-v2 .bag-rlabel { font-size: 18px; line-height: 1.3; white-space: nowrap; }
body #overlay .card.bag-page .bag-v2 .bag-rz .bag-bdg {
  position: absolute; top: -6px; right: -6px; min-width: 28px; height: 28px; padding: 0 6px;
  border-radius: 10px; background: rgba(255, 255, 255, .14); color: #f2f4f6;
  font-size: 16px; font-weight: 700; line-height: 28px; font-variant-numeric: tabular-nums;
}
body #overlay .card.bag-page .bag-v2 .bag-rz:hover:enabled { color: #f2f4f6; background: rgba(255, 255, 255, .08); transform: translateY(-1px); }
body #overlay .card.bag-page .bag-v2 .bag-rz.on { color: #101319; background: #f5d97b; box-shadow: 0 6px 22px rgba(245, 217, 123, .35); }
body #overlay .card.bag-page .bag-v2 .bag-rz.on .bag-bdg { background: #101319; color: #f5d97b; }
body #overlay .card.bag-page .bag-v2 .bag-rz.drop-here { outline: 2px dashed #f5d97b; outline-offset: 2px; }
body #overlay .card.bag-page .bag-v2 .bag-rlogo { margin-top: auto; font-size: 10px; letter-spacing: .3em; color: rgba(226, 232, 238, .34); writing-mode: vertical-rl; }
/* 中列：标题 / 容量 / 资产（横排分割线分隔头/工具/网格三段） */
body #overlay .card.bag-page .bag-v2 .bag-col { display: flex; flex-direction: column; min-width: 0; min-height: 0; gap: 0; }
body #overlay .card.bag-page .bag-v2 .bag-head2 {
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: 12px 20px; padding: 4px 6px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .14);
}
body #overlay .card.bag-page .bag-v2 .bag-kick { display: block; font-size: 10px; letter-spacing: .42em; color: rgba(226, 232, 238, .34); }
body #overlay .card.bag-page .bag-v2 .bag-head2 h2 { display: flex; align-items: center; gap: 14px; margin: 2px 0 0; font-size: 40px; font-weight: 800; letter-spacing: .06em; line-height: 1.2; color: #f2f4f6; }
body #overlay .card.bag-page .bag-v2 .bag-title .help-btn { width: 60px; height: 60px; font-size: 22px; flex: none; }
/* Match the shared archive-back ID specificity; geometry stays scoped to this rail. */
body #overlay#overlay#overlay .card.bag-page .bag-v2 .bag-rail > .archive-back { position: static; inset: auto; flex: none; margin: 0 0 20px; width: 64px; height: 64px; }
body #overlay .card.bag-page .bag-v2 .bag-capchip {
  margin-left: auto; display: flex; align-items: center; gap: 10px; padding: 0; border-radius: 0;
  background: none; border: 0; box-shadow: none;
}
body #overlay .card.bag-page .bag-v2 .bag-capk { font-size: 18px; letter-spacing: .12em; color: #aebfc9; }
body #overlay .card.bag-page .bag-v2 .bag-capbar { position: relative; width: 130px; height: 8px; border-radius: 4px; background: rgba(255, 255, 255, .10); overflow: hidden; }
body #overlay .card.bag-page .bag-v2 .bag-capbar i { position: absolute; inset: 0 auto 0 0; border-radius: 4px; background: linear-gradient(90deg, #d8b054, #f5d97b); }
body #overlay .card.bag-page .bag-v2 .bag-capchip b { font-size: 28px; font-variant-numeric: tabular-nums; }
body #overlay .card.bag-page .bag-v2 .bag-capchip small { font-size: 20px; color: #b7c7cf; font-variant-numeric: tabular-nums; }
body #overlay .card.bag-page .bag-v2 .bag-cur { display: flex; gap: 20px; align-items: flex-end; }
body #overlay .card.bag-page .bag-v2 .bag-tools {
  display: flex; align-items: center; gap: 8px; padding: 16px 2px;
  border-bottom: 1px solid rgba(255, 255, 255, .09);
}
body #overlay .card.bag-page .bag-v2 .bag-pill {
  border: 1px solid transparent; background: rgba(255, 255, 255, .06); color: #93a7b1;
  min-height: 60px; font-size: 22px; padding: 10px 22px; border-radius: 999px; cursor: pointer; font-family: inherit; letter-spacing: .04em;
  transition: background .2s, color .2s;
}
body #overlay .card.bag-page .bag-v2 .bag-pill:hover:enabled { color: #f2f4f6; background: rgba(255, 255, 255, .11); }
body #overlay .card.bag-page .bag-v2 .bag-pill.on { background: #f5d97b; color: #101319; font-weight: 700; }
body #overlay .card.bag-page .bag-v2 .bag-receipt { margin: 0 0 12px; padding: 10px 14px; color: #f5d97b; border: 1px solid #f5d97b66; border-radius: 10px; background: #101319dd; }
body #overlay .card.bag-page .bag-v2 button:focus-visible { outline: 2px solid #f5d97b; outline-offset: 3px; }
body #overlay .card.bag-page .bag-v2 .bag-tgap { flex: 1; }
body #overlay .card.bag-page .bag-v2 .bag-icbtn {
  width: 60px; height: 60px; flex: none; border-radius: 12px; border: 1px solid rgba(255, 255, 255, .12); cursor: pointer;
  background: rgba(255, 255, 255, .06); color: #c9d4dc; display: flex; align-items: center; justify-content: center;
  transition: background .2s, color .2s;
}
body #overlay .card.bag-page .bag-v2 .bag-icbtn svg { width: 26px; height: 26px; }
body #overlay .card.bag-page .bag-v2 .bag-icbtn:hover:enabled { color: #fff; background: rgba(255, 255, 255, .13); }
body #overlay .card.bag-page .bag-v2 .bag-icbtn.gold { background: #f5d97b; border-color: #f5d97b; color: #101319; }
/* 网格板 */
body #overlay .card.bag-page .bag-v2 .bag-board { flex: 1; min-height: 0; margin-top: 16px; padding: 16px 20px; overflow-y: auto; scrollbar-color: rgba(255, 255, 255, .18) transparent; }
body #overlay .card.bag-page .bag-v2 .bag-znote { margin: 0 0 14px; font-size: 22px; line-height: 1.55; letter-spacing: .02em; color: #b7c7cf; }
/* 一行固定五列（老板定向），格子走卡面比例，卡面放大占满格子 */
body #overlay .card.bag-page .bag-v2 .bag-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px; padding: 0; background: none; border: 0; }
body #overlay .card.bag-page .bag-v2 .bag-empty2 { margin: 8px 2px; color: #b7c7cf; font-size: 22px; }
body #overlay .card.bag-page .bag-v2 .bag-tile {
  position: relative; aspect-ratio: 5 / 7.4; height: auto; border-radius: 16px; cursor: pointer; overflow: hidden;
  background: var(--tint, rgba(255, 255, 255, .055)); border: 1px solid transparent;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  transition: transform .2s, border-color .2s;
}
/* 真实卡面格（老板反馈接入现行卡面并放大）：卡面自带名称/费用/框体，格底保留稀有度晕染 */
body #overlay .card.bag-page .bag-v2 .bag-tile.card-face { padding-top: 3.2%; justify-content: flex-start; }
body #overlay .card.bag-page .bag-v2 .bag-tile.card-face .hs-card {
  width: calc(var(--game-layout-width, 100vw) * 0.142); max-width: calc(100% - 12px);
  font-size: calc(var(--game-layout-width, 100vw) * 0.0142); margin: 0; flex: none;
}
body #overlay .card.bag-page .bag-v2 .bag-tile.card-face .bag-tstate {
  bottom: 8px; left: 50%; right: auto; transform: translateX(-50%); width: max-content; z-index: 3;
  background: rgba(8, 10, 15, .6); backdrop-filter: blur(8px); border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 999px; padding: 2px 12px; letter-spacing: .14em;
}
body #overlay .card.bag-page .bag-v2 .bag-tile::before {
  content: ""; position: absolute; inset: 0; border-radius: 16px;
  background: radial-gradient(90% 62% at 50% 26%, var(--glow, rgba(255, 255, 255, .07)), transparent 72%); pointer-events: none;
}
/* Real card hosts and their count badges move together through card-state-motion.
   Leave decorative supply slots on the CSS hover path, outside drag ownership. */
body #overlay .card.bag-page .bag-v2 .bag-tile:not(.card-face):hover { transform: translateY(-3px); border-color: rgba(255, 255, 255, .18); }
body #overlay .card.bag-page .bag-v2 .bag-tile.sel { border-color: #f5d97b; box-shadow: 0 0 0 1.5px #f5d97b, 0 10px 30px rgba(0, 0, 0, .35); }
body #overlay .card.bag-page .bag-v2 .bag-tile:focus-visible { outline: 2px solid #f5d97b; outline-offset: 2px; }
body #overlay .card.bag-page .bag-v2 .bag-tile.dragging { opacity: .32; border-style: dashed; }
body #overlay .card.bag-page .bag-v2 .bag-tile.drop-here { border-color: #f5d97b !important; box-shadow: inset 0 0 0 2px #f5d97b; }
body #overlay .card.bag-page .bag-v2 .bag-tile.spent { filter: saturate(.3) brightness(.8); }
body #overlay .card.bag-page .bag-v2 .bag-tico { width: 52px; height: 52px; z-index: 1; }
body #overlay .card.bag-page .bag-v2 .bag-tico svg { width: 100%; height: 100%; }
