    & .warehouse-toolbar :is(input,select) { min-height:var(--ui-control-compact); padding:var(--ui-space-2) var(--ui-space-3); border:1px solid var(--camp-line); border-radius:9px; background:#10171ab3; color:var(--camp-ink); font-size:var(--ui-text-label); }
    & .warehouse-toolbar input { width:280px; }
    & .warehouse-toolbar select { width:200px; }
