    & .warehouse-workspace-v12 { display:grid; flex:1; min-height:0; overflow:hidden; grid-column:auto; grid-row:auto; grid-template-columns:minmax(0,1fr); grid-template-rows:minmax(0,1fr); align-items:stretch; }
    & .warehouse-inventory-v12 { display:flex; flex-direction:column; min-height:0; overflow:hidden; min-width:0; padding:8px; border:1px solid var(--camp-line); border-radius:18px; background:var(--base-v12-glass,rgba(22,29,35,.46)); }
    & .card-browser { display:flex; flex-direction:column; flex:1; min-height:0; overflow:hidden; --card-browser-min:112px; --card-browser-gap:12px; margin:0; }
    & .card-browser-track { display:grid; min-height:0; max-height:none; overflow-x:hidden; overflow-y:auto; flex:1; grid-auto-flow:row; grid-auto-rows:minmax(480px,max-content); align-content:start; align-items:start; gap:24px; padding:8px 12px; scrollbar-width:thin; scrollbar-color:#65818b transparent; overscroll-behavior-y:contain; }
    & .stash-cell { display:flex; flex-direction:column; align-items:center; position:relative; box-sizing:border-box; width:100%; max-width:none; height:auto; min-height:480px; min-width:0; padding:8px 12px; gap:8px; border:2px solid #eaf5ed25; border-radius:12px; background:#10161beb; box-shadow:0 3px 0 #080d10; color:var(--camp-ink); }
    & .stash-cell:hover { transform:none; background:#2a3436ed; }
    & .stash-cell.selected { border:2px solid var(--camp-accent); background:#24434bf0; box-shadow:0 0 0 2px #9edce733; }
    & .warehouse-card-art { display:block; flex:none; width:300px; max-width:100%; height:auto; min-height:0; aspect-ratio:2/3; overflow:visible; margin:0; }
    & .warehouse-card-art .hs-card { box-sizing:border-box; flex:none; width:100%!important; max-width:none!important; font-size:16px; margin:0; }
    & .stash-card-caption { display:flex; flex:none; align-items:center; justify-content:flex-end; width:100%; margin-top:auto; padding:0; overflow:hidden; }
    & .stash-card-caption b { display:none; }
    & .stash-cell .stack-count { position:static; display:block; min-width:48px; padding:4px 8px; border:1px solid #d6e7e766; border-radius:8px; background:#081015cc; color:#f5f7ee; font:bold var(--base-type-label,19px)/1.15 var(--font-num,sans-serif); text-align:center; }
    & .warehouse-protected { position:absolute; top:8px; right:8px; padding:3px 5px; border-radius:6px; background:#10191bd9; color:#d7e5b4; font-size:var(--base-type-label,19px); }
