    & .card-browser-page { width:var(--ui-control-compact); height:var(--ui-control-compact); border-radius:16px; color:var(--camp-ink); font-size:var(--base-type-label,19px); }
    & .warehouse-no-results { padding:36px 20px; color:var(--camp-muted); }
  }

